import {api,money,date,toast} from './api.js';
const root=document.querySelector('#app'), path=location.pathname, state={user:null,settings:null,appointments:[],tickets:[]};
const pref=JSON.parse(localStorage.getItem('fa-accessibility')||'{}');
let fieldSequence=0;function connectLabels(scope=document){scope.querySelectorAll('.field').forEach(field=>{const control=field.querySelector('input,select,textarea'),label=field.querySelector('label');if(control&&label){if(!control.id)control.id='fa-field-'+(++fieldSequence);label.htmlFor=control.id;if(!control.getAttribute('aria-describedby')){const help=field.querySelector('small');if(help){if(!help.id)help.id=control.id+'-help';control.setAttribute('aria-describedby',help.id)}}}});const topbar=scope.querySelector('.topbar');if(topbar&&!topbar.querySelector('.topbar-brand'))topbar.insertAdjacentHTML('afterbegin','<a class="topbar-brand" href="/" aria-label="Fernanda Azevedo"><img src="/assets/brand/fernanda-azevedo-logo.svg" alt=""></a>');scope.querySelectorAll('img[src*="fernanda-azevedo-logo"]').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.parentElement?.insertAdjacentHTML('beforeend','<span class="logo-fallback">FA</span>')},{once:true}))}
new MutationObserver(()=>connectLabels(root)).observe(root,{childList:true,subtree:true});
new MutationObserver(()=>document.querySelectorAll('.sidebar .brand-logo img,.brand-logo--light img').forEach(img=>{if(!img.src.endsWith('fernanda-azevedo-logo-light.svg'))img.src='/assets/brand/fernanda-azevedo-logo-light.svg'})).observe(root,{childList:true,subtree:true});
function applyPreferences(){const h=document.documentElement;h.classList.toggle('dark',!!pref.dark);h.classList.toggle('high-contrast',!!pref.contrast);h.classList.toggle('reduce-motion',!!pref.motion);h.classList.remove('font-large','font-xlarge');if(pref.font===1)h.classList.add('font-large');if(pref.font===2)h.classList.add('font-xlarge')}
function savePreferences(){localStorage.setItem('fa-accessibility',JSON.stringify(pref));applyPreferences()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titleCase=s=>String(s||'').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const status=s=>`<span class="badge ${/BLOCK|CRIT|FAILED/.test(s)?'danger':/WAIT|PENDING/.test(s)?'warning':''}">${esc(titleCase(s))}</span>`;
async function init(){applyPreferences();if(isAuth())return renderAuth();try{state.user=await api('/api/auth/me');state.settings=await api('/api/public/settings');await loadData();renderShell();renderPage()}catch(e){location.href='/login?next='+encodeURIComponent(path)}}
function isAuth(){return ['/login','/cadastro','/esqueci-senha','/redefinir-senha','/termos','/privacidade'].includes(path)}
async function loadData(){const calls=[api('/api/appointments').catch(()=>[]),api('/api/tickets').catch(()=>[])];[state.appointments,state.tickets]=await Promise.all(calls)}
function renderAuth(){const kind=path.split('/')[1]||'login';root.innerHTML=`<main class="auth-page"><aside class="auth-aside"><a class="brand brand-logo brand-logo--light" href="/"><img src="/assets/brand/fernanda-azevedo-logo.svg" alt="Fernanda Azevedo"></a><span class="eyebrow" style="color:var(--brown-200);margin-top:60px">Cuidado digital, presença humana</span><h1>Seu cuidado, mais perto.</h1><p>Uma experiência segura e acolhedora, criada para você se sentir acompanhado em cada etapa.</p></aside><section class="auth-main"><div class="auth-card">${authContent(kind)}</div></section></main><button class="a11y-fab" aria-label="Abrir acessibilidade">♿</button>`;bindAuth(kind);document.querySelector('.a11y-fab').onclick=showAccessibility}
function authContent(k){if(k==='termos'||k==='privacidade')return `<a href="/">← Voltar</a><h1>${k==='termos'?'Termos de Uso':'Política de Privacidade'}</h1><p>Versão demonstrativa 2.1 • vigente desde 20/08/2026</p><div class="panel"><h3>Transparência e cuidado</h3><p>Este documento demonstra finalidades, direitos, bases de tratamento e responsabilidades. Dados de saúde exigem proteção reforçada. O protótipo não substitui validação jurídica, de privacidade e direção técnica antes da produção.</p><p>Solicitações sobre dados pessoais serão avaliadas conforme a legislação e obrigações de guarda aplicáveis.</p></div>`;
if(k==='cadastro')return `<a href="/login">← Entrar</a><h1>Criar conta</h1><p>Comece sua jornada com segurança.</p><form id="signup"><div class="field"><label>Nome completo</label><input name="name" required></div><div class="form-grid"><div class="field"><label>CPF demonstrativo</label><input name="document" placeholder="000.000.000-00" pattern="\d{3}\.\d{3}\.\d{3}-\d{2}" required></div><div class="field"><label>Data de nascimento</label><input type="date" name="birth" required></div></div><div class="field"><label>E-mail</label><input type="email" name="email" required></div><div class="field"><label>Telefone</label><input name="phone" required></div><div class="form-grid"><div class="field"><label>Senha</label><input type="password" name="password" required></div><div class="field"><label>Confirmar senha</label><input type="password" name="confirm" required></div></div><label class="check"><input type="checkbox" name="terms" required><span>Li e aceito os <a href="/termos" target="_blank"><u>Termos de Uso</u></a>.</span></label><label class="check"><input type="checkbox" name="privacy" required><span>Li a <a href="/privacidade" target="_blank"><u>Política de Privacidade</u></a>.</span></label><button class="btn btn-primary" type="submit">Criar minha conta</button></form>`;
if(k==='esqueci-senha')return `<a href="/login">← Entrar</a><h1>Recuperar senha</h1><p>Informe seu e-mail. A resposta será neutra para proteger sua conta.</p><form id="forgot"><div class="field"><label>E-mail</label><input type="email" name="email" required></div><button class="btn btn-primary">Enviar instruções</button></form>`;
if(k==='redefinir-senha')return `<a href="/login">← Entrar</a><h1>Definir nova senha</h1><form id="reset"><div class="field"><label>E-mail</label><input type="email" name="email" required></div><div class="field"><label>Nova senha</label><input type="password" name="password" required><small>8+ caracteres, maiúscula, minúscula, número e especial.</small></div><button class="btn btn-primary">Alterar senha</button></form>`;
return `<a href="/">← Voltar ao site</a><h1>Boas-vindas</h1><p>Entre para acessar sua experiência.</p><form id="login"><div class="field"><label>E-mail</label><input type="email" name="email" autocomplete="username" required></div><div class="field"><label>Senha</label><input type="password" name="password" autocomplete="current-password" required></div><label class="check"><input type="checkbox" name="remember"><span>Lembrar-me</span></label><button class="btn btn-primary" type="submit">Entrar</button> <button class="btn btn-ghost" type="button" id="google">Entrar com Google <small>(simulado)</small></button></form><p><a href="/esqueci-senha"><u>Esqueci minha senha</u></a> · <a href="/cadastro"><u>Criar conta</u></a></p><div class="demo-users"><b>Contas demonstrativas</b><br>paciente@fernandaazevedo.demo<br>medico@fernandaazevedo.demo<br>suporte@fernandaazevedo.demo<br>admin@fernandaazevedo.demo<br>Senha: <b>Demo@123</b></div>`}
function bindAuth(k){const f=document.querySelector('form');if(!f)return;if(k==='login'){f.onsubmit=async e=>{e.preventDefault();try{const u=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});location.href=new URLSearchParams(location.search).get('next')||`/${rolePath(u.role)}/dashboard`}catch(x){toast(x.message)}};document.querySelector('#google').onclick=()=>toast('Login Google simulado: integração OAuth será conectada em produção.')}else if(k==='forgot')f.onsubmit=async e=>{e.preventDefault();const r=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});toast(r.message);setTimeout(()=>location.href='/redefinir-senha',1000)};else if(k==='reset')f.onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});toast(r.message);setTimeout(()=>location.href='/login',1000)}catch(x){toast(x.message)}};else if(k==='cadastro')f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f));if(b.password!==b.confirm)return toast('As senhas não conferem.');if(!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/.test(b.password))return toast('A senha não atende aos requisitos.');try{await api('/api/auth/register',{method:'POST',body:JSON.stringify(b)});toast('Conta criada e consentimentos registrados. Entre para continuar.');setTimeout(()=>location.href='/login',1200)}catch(x){toast(x.message)}}}
function rolePath(r){return ({PATIENT:'paciente',DOCTOR:'medico',SUPPORT:'suporte',ADMIN:'admin'})[r]}
function nav(){const r=state.user.role,base='/'+rolePath(r);const menus={PATIENT:[['dashboard','Visão geral'],['consultar','Consultar agora'],['historico','Histórico'],['documentos','Documentos'],['suporte','Suporte'],['privacidade','Privacidade'],['perfil','Meu perfil']],DOCTOR:[['dashboard','Visão geral'],['fila','Fila'],['agenda','Agenda'],['historico','Histórico'],['financeiro','Financeiro'],['suporte','Suporte'],['privacidade','Privacidade'],['perfil','Meu perfil']],SUPPORT:[['dashboard','Visão geral'],['tickets','Tickets'],['usuarios','Usuários'],['perfil','Meu perfil']],ADMIN:[['dashboard','Visão geral'],['usuarios','Usuários'],['permissoes','Permissões'],['consultas','Consultas'],['pagamentos','Pagamentos'],['tickets','Tickets'],['campanhas','Campanhas'],['configuracoes/valores','Valores e operação'],['consentimentos','Consentimentos'],['auditoria','Auditoria'],['perfil','Meu perfil']]};return menus[r].map(([p,l])=>`<a href="${base}/${p}" class="${path.startsWith(base+'/'+p)?'active':''}">${l}</a>`).join('')}
function renderShell(){root.innerHTML=`<div class="app-shell"><div class="sidebar-overlay" aria-hidden="true"></div><aside class="sidebar" aria-label="Menu principal"><button class="icon-btn sidebar-close" aria-label="Fechar menu">×</button><button class="sidebar-handle" aria-label="Arrastar menu">›</button><a class="brand brand-logo" href="/"><img src="/assets/brand/fernanda-azevedo-logo.svg" alt="Fernanda Azevedo"></a><nav class="nav-group">${nav()}</nav><footer><button class="btn btn-ghost" id="logout">Sair com segurança</button></footer></aside><div class="app-main"><header class="topbar"><button class="icon-btn mobile-menu" aria-label="Abrir menu" aria-expanded="false">☰</button><div><b>${greeting()}, ${esc(state.user.name.split(' ')[0])}</b><small style="display:block;color:var(--text-secondary)">${titleCase(state.user.role)}</small></div><div class="topbar-actions"><button class="icon-btn" aria-label="Notificações">🔔</button><button class="icon-btn" id="open-a11y" aria-label="Configurações de acessibilidade">◐</button><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span></div></header><main id="main" class="content"></main></div></div><button class="a11y-fab" aria-label="Abrir acessibilidade">♿</button>`;bindShell()}
function bindShell(){const side=document.querySelector('.sidebar'),overlay=document.querySelector('.sidebar-overlay'),menu=document.querySelector('.mobile-menu');const open=()=>{side.classList.add('open');overlay.classList.add('show');menu.setAttribute('aria-expanded','true')},close=()=>{side.classList.remove('open');overlay.classList.remove('show');menu.setAttribute('aria-expanded','false')};menu.onclick=open;overlay.onclick=close;document.querySelector('.sidebar-close').onclick=close;let startX=0,currentX=0;side.addEventListener('touchstart',e=>{startX=e.touches[0].clientX},{passive:true});side.addEventListener('touchmove',e=>{currentX=e.touches[0].clientX;if(currentX<startX)side.style.transform=`translateX(${Math.max(-260,currentX-startX)}px)`},{passive:true});side.addEventListener('touchend',()=>{if(currentX&&startX-currentX>70)close();side.style.transform='';startX=currentX=0});document.addEventListener('touchstart',e=>{if(innerWidth<981&&e.touches[0].clientX<24)startX=e.touches[0].clientX},{passive:true});document.addEventListener('touchend',e=>{if(startX<24&&e.changedTouches[0].clientX-startX>75)open();startX=0},{passive:true});document.querySelector('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.href='/login'};document.querySelector('#open-a11y').onclick=showAccessibility;document.querySelector('.a11y-fab').onclick=showAccessibility}
function showAccessibility(){const existing=document.querySelector('.a11y-panel');if(existing)return existing.remove();document.body.insertAdjacentHTML('beforeend',`<section class="a11y-panel" aria-label="Configurações de acessibilidade"><h2>Acessibilidade e aparência</h2><div class="setting-row"><span>Tamanho do texto</span><div class="setting-actions"><button data-font="0" aria-label="Texto padrão">A</button><button data-font="1" aria-label="Texto grande">A+</button><button data-font="2" aria-label="Texto muito grande">A++</button></div></div><label class="setting-row"><span>Modo noturno</span><input id="pref-dark" type="checkbox" ${pref.dark?'checked':''}></label><label class="setting-row"><span>Alto contraste</span><input id="pref-contrast" type="checkbox" ${pref.contrast?'checked':''}></label><label class="setting-row"><span>Reduzir animações</span><input id="pref-motion" type="checkbox" ${pref.motion?'checked':''}></label><button class="btn btn-primary" id="close-a11y" style="width:100%;margin-top:16px">Concluir</button></section>`);document.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>{pref.font=Number(b.dataset.font);savePreferences()});['dark','contrast','motion'].forEach(k=>document.querySelector('#pref-'+k).onchange=e=>{pref[k]=e.target.checked;savePreferences()});document.querySelector('#close-a11y').onclick=()=>document.querySelector('.a11y-panel').remove()}
function greeting(){const h=new Date().getHours();return h<12?'Bom dia':h<18?'Boa tarde':'Boa noite'}
function head(t,s,a=''){return `<div class="page-head"><div><h1>${t}</h1><p>${s}</p></div>${a}</div>`}
function renderPage(){const main=document.querySelector('#main'), section=path.split('/').filter(Boolean).slice(1).join('/');if(section==='dashboard')return dashboard(main);if(section==='consultar'||section==='pagamento')return checkout(main);if(section==='pre-anamnese')return anamnesis(main);if(section==='teste-dispositivos')return devices(main);if(section==='fila')return queue(main);if(section.startsWith('consulta/'))return consultation(main);if(section.startsWith('historico'))return history(main);if(section==='documentos')return documents(main);if(section.startsWith('suporte')||section==='tickets')return support(main);if(section==='financeiro'||section==='pagamentos')return finance(main);if(section==='usuarios')return users(main);if(section==='permissoes')return permissions(main);if(section==='campanhas')return campaigns(main);if(section==='configuracoes/valores'||section==='configuracoes')return settings(main);if(section==='consentimentos'||section==='privacidade')return privacy(main);if(section==='auditoria')return audits(main);if(section==='agenda'||section==='consultas')return history(main);return profile(main)}
function dashboard(m){const role=state.user.role;const labels=role==='ADMIN'?[['Pacientes ativos','124'],['Médicos ativos','18'],['Consultas hoje','32'],['Tickets abertos',state.tickets.length]]:role==='SUPPORT'?[['Aguardando','7'],['Em atendimento','4'],['Aguardando usuário','3'],['Resolvidos hoje','11']]:role==='DOCTOR'?[['Consultas hoje','6'],['Pacientes na fila','2'],['Ganhos do dia',money(300)],['Ganhos no mês',money(4750)]]:[['Próxima consulta','Hoje, 15:30'],['Documentos','3'],['Tickets abertos',state.tickets.length],['Última consulta','20 ago']];m.innerHTML=head('Visão geral','Acompanhe o que precisa de atenção.')+`<section class="metrics">${labels.map(x=>`<article class="metric"><span>${x[0]}</span><strong>${x[1]}</strong></article>`).join('')}</section><div class="grid-2"><section class="panel"><div class="panel-head"><h2>${role==='PATIENT'?'Seus atendimentos recentes':'Atividade operacional'}</h2></div>${appointmentTable(state.appointments)}</section><section class="panel"><div class="panel-head"><h2>Próximos passos</h2></div><p>${role==='PATIENT'?'Você pode iniciar uma nova consulta ou revisar seus documentos.':role==='DOCTOR'?'Há pacientes prontos para atendimento na fila.':role==='SUPPORT'?'Existem tickets sem atendente aguardando na fila.':'Configurações e campanhas estão funcionando normalmente.'}</p><a class="btn btn-primary" href="/${rolePath(role)}/${role==='PATIENT'?'consultar':role==='DOCTOR'?'fila':role==='SUPPORT'?'tickets':'configuracoes/valores'}">Abrir</a></section></div>`}
function appointmentTable(a){return `<div class="table-wrap"><table><thead><tr><th>ID</th><th>Paciente/Médico</th><th>Data</th><th>Status</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td>${esc(x.reference)}</td><td>${esc(x.doctor||x.patient||'Aguardando')}</td><td>${esc(x.date||date(x.createdAt))}</td><td>${status(x.status)}</td><td><a class="btn btn-ghost" href="/${rolePath(state.user.role)}/historico/${x.id}">Detalhes</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum atendimento encontrado.</td></tr>'}</tbody></table></div>`}
function checkout(m){m.innerHTML=head('Consultar agora','Confirme o resumo e escolha o pagamento.')+`<div class="grid-2"><section class="panel"><h2>Consulta online</h2><p>Atendimento com clínico geral conforme disponibilidade.</p><div class="price-card"><span>Valor atual</span><strong>${money(state.settings.consultationPrice)}</strong><small>${esc(state.settings.priceText)}</small></div><label class="check"><input id="commercial" type="checkbox"><span>Estou ciente dos termos comerciais demonstrativos.</span></label></section><section class="panel"><h2>Pagamento demonstrativo</h2><div class="field"><label>Forma de pagamento</label><select id="pay-method"><option>PIX simulado</option><option>Cartão simulado</option></select></div><div class="field"><label>Cupom</label><input disabled placeholder="Em breve"></div><button class="btn btn-primary" id="pay">Pagar ${money(state.settings.consultationPrice)}</button><p><small>Nenhum dado real de cartão será armazenado.</small></p></section></div>`;document.querySelector('#pay').onclick=async e=>{if(!document.querySelector('#commercial').checked)return toast('Confirme a ciência dos termos comerciais.');e.currentTarget.disabled=true;e.currentTarget.textContent='Processando…';try{const a=await api('/api/appointments/checkout',{method:'POST'});await api(`/api/appointments/${a.id}/payment/mock-approve`,{method:'POST'});sessionStorage.setItem('appointmentId',a.id);toast('Pagamento aprovado.');setTimeout(()=>location.href='/paciente/pre-anamnese',700)}catch(x){toast(x.message);e.currentTarget.disabled=false}}}
function anamnesis(m){const fields=[['complaint','Qual é a sua principal queixa?'],['started','Há quanto tempo começou?'],['allergies','Possui alguma alergia?'],['conditions','Possui alguma condição de saúde ou comorbidade conhecida?'],['medicines','Usa algum medicamento atualmente?'],['additional','Existe outra informação importante que gostaria de contar ao médico?']];m.innerHTML=head('Pré-anamnese digital','Antes de falar com o médico, conte um pouco sobre o que está acontecendo. Suas respostas serão enviadas ao profissional responsável pelo seu atendimento.')+`<div class="flow-steps">${fields.map((_,i)=>`<span class="${i===0?'active':''}"></span>`).join('')}</div><form class="panel" id="anamnesis">${fields.map(([n,l],i)=>`<div class="field"><label>${i+1}. ${l}</label><textarea name="${n}" required placeholder="${i>1?'Se não souber, escreva “Não sei informar”.':'Conte com suas palavras.'}"></textarea></div>`).join('')}<p class="restricted">Este formulário não realiza diagnóstico, não prescreve e não substitui avaliação médica.</p><button class="btn btn-primary">Salvar e testar dispositivos</button></form>`;const f=document.querySelector('#anamnesis');f.querySelectorAll('textarea').forEach((x,i)=>x.oninput=()=>document.querySelectorAll('.flow-steps span')[i].classList.add('done'));f.onsubmit=async e=>{e.preventDefault();const id=sessionStorage.getItem('appointmentId')||state.appointments[0]?.id;if(!id)return toast('Inicie uma consulta antes.');await api(`/api/appointments/${id}/pre-anamnesis`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(f)))});location.href='/paciente/teste-dispositivos'}}
function devices(m){m.innerHTML=head('Teste de câmera e microfone','Nada será gravado. Você controla seus dispositivos.')+`<div class="grid-2"><section class="panel"><div class="device-preview"><video id="preview" autoplay muted playsinline></video><span id="preview-help">Clique em “Permitir dispositivos”</span></div><div class="audio-meter"><span id="meter"></span></div></section><section class="panel"><div class="field"><label>Câmera</label><select id="camera"><option>Seleção automática</option></select></div><div class="field"><label>Microfone</label><select id="microphone"><option>Seleção automática</option></select></div><button class="btn btn-secondary" id="allow">Permitir dispositivos</button> <button class="btn btn-ghost" id="speaker">Testar alto-falante</button><label class="check"><input id="confirmed" type="checkbox"><span>Consigo me ver e confirmo que o áudio está pronto.</span></label><button class="btn btn-primary" id="continue" disabled>Continuar para a fila</button><p id="device-status"></p></section></div>`;const confirmed=document.querySelector('#confirmed'),cont=document.querySelector('#continue');confirmed.onchange=()=>cont.disabled=!confirmed.checked;cont.onclick=()=>location.href='/paciente/fila';document.querySelector('#speaker').onclick=()=>{toast('Som de teste reproduzido (simulação).')};document.querySelector('#allow').onclick=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});const v=document.querySelector('#preview');v.srcObject=stream;document.querySelector('#preview-help').remove();document.querySelector('#device-status').textContent='Câmera e microfone disponíveis.';const list=await navigator.mediaDevices.enumerateDevices();for(const d of list){const sel=document.querySelector(d.kind==='videoinput'?'#camera':d.kind==='audioinput'?'#microphone':'x');if(sel){const o=document.createElement('option');o.textContent=d.label||'Dispositivo disponível';sel.append(o)}}const ctx=new AudioContext(),an=ctx.createAnalyser();ctx.createMediaStreamSource(stream).connect(an);const data=new Uint8Array(an.frequencyBinCount);const tick=()=>{an.getByteFrequencyData(data);document.querySelector('#meter').style.width=Math.min(100,8+Math.max(...data)/2)+'%';requestAnimationFrame(tick)};tick()}catch(e){document.querySelector('#device-status').innerHTML='<span class="badge danger">Permissão negada</span> Libere câmera e microfone nas configurações do navegador.'}}}
function queue(m){m.innerHTML=head('Sala de espera','Seu atendimento está sendo preparado.')+`<section class="panel" style="text-align:center;padding:60px"><span class="spinner" style="display:inline-block"></span><h2>Localizando um médico disponível</h2><p>Posição demonstrativa na fila: <b>1 de 2</b></p><p>Tempo estimado: aproximadamente 3 minutos.</p><a class="btn btn-primary" href="/paciente/consulta/${sessionStorage.getItem('appointmentId')||42}">Entrar na consulta demonstrativa</a></section>`}
function consultation(m){const isDoctor=state.user.role==='DOCTOR';m.innerHTML=head('Teleconsulta','Ambiente protegido • a consulta não está sendo gravada')+`<div class="chat-layout"><section class="video-stage"><div class="video-topbar"><span><span class="badge">Conexão estável</span></span><strong id="timer">00:00</strong></div><div class="video-placeholder"><span class="avatar">${isDoctor?'JA':'FA'}</span><h2>${isDoctor?'João Almeida':'Dra. Fernanda Azevedo'}</h2><p>${isDoctor?'Paciente':'Clínica geral • CRM DEMO'}</p></div><video class="self-video" id="self" autoplay muted playsinline aria-label="Sua câmera"></video><div class="video-controls"><button class="round-btn" id="mic" aria-label="Desativar microfone" title="Microfone">🎙️</button><button class="round-btn" id="cam" aria-label="Desativar câmera" title="Câmera">📹</button><button class="round-btn" id="devices-call" aria-label="Configurar dispositivos" title="Dispositivos">⚙️</button><button class="round-btn leave-call" id="leave" aria-label="Sair da sala sem finalizar" title="Sair">↗</button><button class="round-btn end-call" id="end" aria-label="Finalizar consulta" title="Finalizar">⏹</button></div></section><section class="panel chat-panel"><div class="panel-head"><div><h3>Chat clínico</h3><small>Vinculado a esta consulta</small></div><span class="badge">Seguro</span></div><div class="chat-toolbar"><button class="attach-btn" id="files" aria-label="Anexar documento, imagem ou áudio" title="Anexar arquivo">📎</button><button class="attach-btn" id="documents-call" aria-label="Ver documentos da consulta" title="Documentos">▤</button><span id="upload-status"><small>PDF, imagens, DOCX ou áudio</small></span></div><div class="messages" id="messages"><div class="message">Olá! Já li suas respostas. Como você está se sentindo agora?<small><br>Entregue • agora</small></div></div><form class="composer" id="chat"><input aria-label="Mensagem clínica" required placeholder="Escreva uma mensagem"><button class="btn btn-primary">Enviar</button></form><input id="upload" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.doc,.docx,.wav,.mp3,.m4a" hidden></section></div>`;let stream=null,secs=0;const timer=setInterval(()=>{secs++;const el=document.querySelector('#timer');if(el)el.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;else clearInterval(timer)},1000);startConsultationCamera();async function startConsultationCamera(){try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});document.querySelector('#self').srcObject=stream;toast('Sua câmera e seu microfone estão ativos.')}catch(e){toast('Não foi possível abrir sua câmera. Verifique a permissão do navegador.');document.querySelector('#self').setAttribute('poster','/assets/icons/medical-chatbot.svg')}}const form=document.querySelector('#chat');form.onsubmit=e=>{e.preventDefault();const i=form.querySelector('input');addMessage(i.value,true);i.value=''};document.querySelector('#files').onclick=()=>document.querySelector('#upload').click();document.querySelector('#upload').onchange=async e=>{document.querySelector('#upload-status').innerHTML='<small>Analisando arquivo…</small>';await uploadFile(e);document.querySelector('#upload-status').innerHTML='<small>Arquivo processado pelo scanner demonstrativo</small>'};document.querySelector('#documents-call').onclick=()=>modal(`<h2>Documentos da consulta</h2><div class="file-preview"><span>📄</span><div><b>Orientações do atendimento</b><small><br>Documento demonstrativo</small></div></div><div class="file-preview"><span>▤</span><div><b>Solicitação de exame</b><small><br>Sem validade médica real</small></div></div>`);document.querySelector('#devices-call').onclick=()=>modal(`<h2>Dispositivos em uso</h2><p>Câmera e microfone estão selecionados automaticamente. Você pode desligá-los diretamente na barra da consulta.</p><button class="btn btn-primary" onclick="document.querySelector('.modal .icon-btn').click()">Entendi</button>`);document.querySelector('#leave').onclick=()=>confirmModal('Sair da sala?','A consulta continuará ativa e você poderá retornar enquanto ela não for finalizada.',()=>{stream?.getTracks().forEach(t=>t.stop());location.href=`/${rolePath(state.user.role)}/dashboard`});document.querySelector('#end').onclick=()=>confirmModal(isDoctor?'Finalizar atendimento?':'Finalizar sua participação?','A consulta será encerrada e o chat ficará disponível no histórico em modo somente leitura.',()=>{stream?.getTracks().forEach(t=>t.stop());toast('Consulta finalizada e salva no histórico.');setTimeout(()=>location.href=`/${rolePath(state.user.role)}/historico`,700)});document.querySelector('#mic').onclick=e=>{const track=stream?.getAudioTracks()[0];if(track)track.enabled=!track.enabled;e.currentTarget.classList.toggle('btn-danger',track&&!track.enabled);e.currentTarget.setAttribute('aria-label',track?.enabled?'Desativar microfone':'Ativar microfone')};document.querySelector('#cam').onclick=e=>{const track=stream?.getVideoTracks()[0];if(track)track.enabled=!track.enabled;e.currentTarget.classList.toggle('btn-danger',track&&!track.enabled);e.currentTarget.setAttribute('aria-label',track?.enabled?'Desativar câmera':'Ativar câmera')}}
function addMessage(t,mine=false,internal=false){document.querySelector('#messages')?.insertAdjacentHTML('beforeend',`<div class="message ${mine?'mine':''} ${internal?'internal':''}">${esc(t)}<small><br>Enviado • agora</small></div>`)}
async function uploadFile(e){const f=e.target.files[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const r=await api('/api/upload',{method:'POST',body:fd});addMessage(`${r.name} — ${r.status}`,true);toast(r.message)}catch(x){toast(x.message)}}
function history(m){m.innerHTML=head(state.user.role==='DOCTOR'?'Histórico de atendimentos':'Histórico de consultas','Pesquise sem perder o contexto do atendimento.')+`<section class="panel"><div class="filters"><input id="search" placeholder="Buscar por ID, médico, paciente ou queixa"><input type="date"><select><option>Todos os status</option><option>Concluída</option><option>Em andamento</option></select></div><div id="appointment-list">${appointmentTable(state.appointments)}</div></section>`;document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelector('#appointment-list').innerHTML=appointmentTable(state.appointments.filter(x=>JSON.stringify(x).toLowerCase().includes(q)))}}
function documents(m){m.innerHTML=head('Documentos','Documentos demonstrativos vinculados às suas consultas.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Consulta</th><th>Data</th><th>Status</th></tr></thead><tbody><tr><td>Orientações do atendimento <small>(DEMONSTRAÇÃO)</small></td><td>FA-CONS-2026-0042</td><td>20 ago 2026</td><td>${status('AVAILABLE')}</td></tr><tr><td>Solicitação de exame <small>(SEM VALIDADE REAL)</small></td><td>FA-CONS-2026-0042</td><td>20 ago 2026</td><td>${status('AVAILABLE')}</td></tr></tbody></table></div></section>`}
function support(m){const supportRole=state.user.role==='SUPPORT'||state.user.role==='ADMIN';m.innerHTML=head(supportRole?'Atendimento e tickets':'Como podemos ajudar?',supportRole?'Uma central completa para atender com agilidade, contexto e cuidado.':'Encontre respostas ou converse com nosso suporte técnico e operacional.')+(supportRole?ticketPanel():botPanel());if(supportRole)bindTickets();else bindBot()}
function botPanel(){return `<section class="support-welcome"><div class="panel support-hero"><span class="eyebrow" style="color:var(--brown-200)">Central de ajuda</span><h2>Conte com a gente em cada etapa.</h2><p>Busque uma resposta rápida ou fale com o Assistente Fernanda Azevedo. Para assuntos clínicos, procure o médico responsável pelo atendimento.</p><input class="help-search" type="search" placeholder="Pesquise: câmera, pagamento, acesso…" aria-label="Pesquisar artigos de ajuda"><div class="quick-options"><button>Conta e acesso</button><button>Pagamento</button><button>Câmera e microfone</button><button>Consulta</button></div></div><section class="panel bot-shell support-bot"><div class="bot-head"><img src="/assets/icons/medical-chatbot.svg" alt="Robô do assistente virtual"><div><h2>Assistente Fernanda Azevedo</h2><small><span class="badge">Online</span> Suporte virtual</small></div></div><div class="messages" id="messages"><div class="message">Olá! Estou aqui para ajudar com acesso, pagamento, dispositivos e uso da plataforma. Não forneço orientação clínica.</div></div><div class="quick-options">${['Não consigo entrar','Problema com pagamento','Câmera ou microfone','Minha consulta não iniciou','Localizar documento','Atualizar meus dados'].map(x=>`<button>${x}</button>`).join('')}</div><div class="actions"><button class="btn btn-secondary" id="resolved">Problema resolvido</button><button class="btn btn-primary" id="need-help">Falar com uma pessoa</button></div></section></section><section class="panel"><div class="panel-head"><div><h2>Meus atendimentos</h2><small>Acompanhe respostas, status e histórico</small></div><button class="btn btn-ghost" id="new-support">Novo atendimento</button></div>${state.tickets.map(x=>`<article class="file-preview"><span>💬</span><div style="flex:1"><b>${esc(x.reference)} · ${esc(x.subject)}</b><small><br>Atualizado recentemente</small></div>${status(x.status)}</article>`).join('')||'<p class="empty">Você ainda não possui tickets.</p>'}</section>`}
function bindBot(){document.querySelectorAll('.quick-options button').forEach(b=>b.onclick=()=>{addMessage(b.textContent,true);setTimeout(()=>addMessage('Vamos verificar isso juntos. Confira as orientações acima; se ainda precisar, conecto você a uma pessoa sem perder este histórico.'),300)});document.querySelector('.help-search')?.addEventListener('input',e=>{if(e.target.value.length>3)toast('Buscando artigos e orientações relacionadas…')});document.querySelector('#resolved').onclick=()=>toast('Que bom! Atendimento do assistente encerrado.');const openTicket=()=>modal(`<h2>Falar com o suporte</h2><p>Seu histórico com o assistente será incluído automaticamente.</p><form id="ticket-form"><div class="field"><label>Categoria</label><select name="category"><option>Conta e acesso</option><option>Pagamento</option><option>Câmera e microfone</option><option>Consulta</option><option>Outro</option></select></div><div class="field"><label>Conte resumidamente o que aconteceu</label><textarea name="subject" required placeholder="Inclua mensagens de erro e o que você já tentou."></textarea></div><div class="field"><label>Urgência operacional</label><select name="priority"><option>NORMAL</option><option>ALTA</option><option>CRITICA_OPERACIONAL</option></select></div><button class="btn btn-primary">Criar ticket e entrar na fila</button></form>`,()=>{const f=document.querySelector('#ticket-form');f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f));const r=await api('/api/records/tickets',{method:'POST',body:JSON.stringify({...b,status:'WAITING_SUPPORT',reference:'FA-2026-'+String(Date.now()).slice(-6),botHistory:true})});closeModal();toast(`Ticket ${r.reference} criado. Nossa equipe já recebeu o histórico.`)}});document.querySelector('#need-help').onclick=openTicket;document.querySelector('#new-support').onclick=openTicket}
function ticketPanel(){const current=state.tickets[0]||{id:0,reference:'Nenhum ticket',subject:'Selecione um atendimento',requester:'—',owner:'—',priority:'NORMAL',status:'OPEN',category:'Geral'};return `<section class="metrics"><article class="metric"><span>Aguardando atendimento</span><strong>${state.tickets.filter(x=>x.status==='WAITING_SUPPORT').length}</strong></article><article class="metric"><span>Em atendimento</span><strong>4</strong></article><article class="metric"><span>Primeira resposta média</span><strong>6 min</strong></article><article class="metric"><span>Resolvidos hoje</span><strong>11</strong></article></section><div class="support-workspace"><section class="panel ticket-list-panel"><div class="ticket-list-head"><h3>Fila de atendimento</h3><div class="field" style="margin:12px 0 0"><input id="ticket-search" placeholder="Buscar ticket ou pessoa" aria-label="Buscar tickets"></div><div class="filters"><select id="ticket-status"><option value="">Todos</option><option>WAITING_SUPPORT</option><option>IN_PROGRESS</option><option>RESOLVED</option></select></div></div><div class="ticket-list" id="tickets-list">${ticketList(state.tickets,current.id)}</div></section><section class="panel ticket-conversation"><div class="panel-head"><div><h2 id="active-ticket-ref">${esc(current.reference)}</h2><small id="active-ticket-subject">${esc(current.subject)}</small></div>${status(current.status)}</div><div class="messages" id="messages"><div class="message"><b>Assistente virtual</b><br>Conversa inicial e verificações automáticas preservadas.</div><div class="message mine">Ainda preciso de ajuda com este problema.</div></div><div class="chat-toolbar"><button class="attach-btn" id="support-attach" aria-label="Anexar arquivo">📎</button><button class="attach-btn" id="support-audio" aria-label="Gravar áudio">🎙️</button><select id="quick-reply" aria-label="Resposta rápida"><option value="">Resposta rápida…</option><option>Olá! Vou analisar seu caso agora.</option><option>Poderia enviar uma captura da tela?</option><option>Realizamos um ajuste. Pode tentar novamente?</option></select></div><form id="support-chat" class="composer"><input required placeholder="Escreva uma resposta acolhedora"><button class="btn btn-primary">Enviar</button></form><div class="actions"><button class="btn btn-ghost" id="note">Nota interna</button><button class="btn btn-ghost" id="transfer">Transferir</button><button class="btn btn-secondary" id="waiting">Aguardar usuário</button><button class="btn btn-primary" id="resolve">Resolver</button></div><input id="support-upload" type="file" hidden></section><aside class="panel ticket-details"><h3>Detalhes</h3><dl><div><dt>Solicitante</dt><dd id="detail-requester">${esc(current.requester||current.owner)}</dd></div><div><dt>Categoria</dt><dd id="detail-category">${esc(current.category||'Geral')}</dd></div><div><dt>Prioridade</dt><dd id="detail-priority">${esc(current.priority||'NORMAL')}</dd></div><div><dt>SLA</dt><dd><span class="badge warning">12 min restantes</span></dd></div><div><dt>Atendente</dt><dd>Marina Costa</dd></div><div><dt>Tags</dt><dd><span class="badge">dispositivos</span></dd></div></dl><button class="btn btn-ghost" id="transcript" style="width:100%">Enviar transcrição</button></aside></div>`}
function ticketList(items,active){return items.map(x=>`<button class="ticket-row ${x.id===active?'active':''}" data-id="${x.id}"><div class="ticket-row-line"><b>${esc(x.reference)}</b>${status(x.status)}</div><p>${esc(x.subject)}</p><div class="ticket-row-line"><small>${esc(x.requester||x.owner)}</small><small>${esc(x.priority||'NORMAL')}</small></div></button>`).join('')||'<p class="empty">A fila está vazia.</p>'}
function ticketTable(items){return `<table><thead><tr><th>Ticket</th><th>Solicitante</th><th>Assunto</th><th>Prioridade</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.reference)}</td><td>${esc(x.requester||x.owner)}</td><td>${esc(x.subject)}</td><td>${esc(x.priority||'NORMAL')}</td><td>${status(x.status)}</td><td><button class="btn btn-ghost open-ticket" data-id="${x.id}">Abrir</button></td></tr>`).join('')}</tbody></table>`}
function bindTickets(){let active=state.tickets[0];const refreshRows=items=>{document.querySelector('#tickets-list').innerHTML=ticketList(items,active?.id);bindRows()};const bindRows=()=>document.querySelectorAll('.ticket-row').forEach(b=>b.onclick=()=>{active=state.tickets.find(x=>x.id==b.dataset.id);document.querySelectorAll('.ticket-row').forEach(r=>r.classList.toggle('active',r===b));document.querySelector('#active-ticket-ref').textContent=active.reference;document.querySelector('#active-ticket-subject').textContent=active.subject;document.querySelector('#detail-requester').textContent=active.requester||active.owner;document.querySelector('#detail-category').textContent=active.category||'Geral';document.querySelector('#detail-priority').textContent=active.priority||'NORMAL'});bindRows();document.querySelector('#ticket-search').oninput=e=>refreshRows(state.tickets.filter(x=>JSON.stringify(x).toLowerCase().includes(e.target.value.toLowerCase())));document.querySelector('#ticket-status').onchange=e=>refreshRows(state.tickets.filter(x=>!e.target.value||x.status===e.target.value));document.querySelector('#support-chat').onsubmit=e=>{e.preventDefault();const i=e.target.querySelector('input');addMessage(i.value,true);i.value='';toast('Resposta enviada e registrada no histórico.')};document.querySelector('#quick-reply').onchange=e=>{if(e.target.value)document.querySelector('#support-chat input').value=e.target.value};document.querySelector('#note').onclick=()=>addMessage('Nota interna: acompanhar retorno e manter contexto técnico.',false,true);document.querySelector('#transfer').onclick=()=>toast('Ticket transferido para Equipe Técnica. Todo o histórico foi preservado.');document.querySelector('#waiting').onclick=()=>toast('Status alterado para Aguardando usuário.');document.querySelector('#resolve').onclick=()=>active&&confirmModal('Resolver este ticket?','O usuário poderá avaliar o atendimento e solicitar reabertura.',async()=>{await api(`/api/records/${active.id}/status`,{method:'POST',body:JSON.stringify({status:'RESOLVED'})});toast('Ticket resolvido com sucesso.')});document.querySelector('#transcript').onclick=()=>toast('Transcrição enviada sem notas internas ou campos restritos.');document.querySelector('#support-attach').onclick=()=>document.querySelector('#support-upload').click();document.querySelector('#support-upload').onchange=uploadFile;document.querySelector('#support-audio').onclick=()=>toast('Gravação de áudio iniciada. Clique novamente para concluir (demonstração).')}
function ticketModal(t){modal(`<h2>${esc(t.reference)}</h2><p>${esc(t.subject)} ${status(t.status)}</p><div class="messages" id="messages"><div class="message">Conversa anterior do chatbot preservada.</div><div class="message mine">Ainda preciso de ajuda.</div></div><form id="support-chat" class="composer"><input required placeholder="Responder"><button class="btn btn-primary">Enviar</button></form><div class="actions"><button class="btn btn-secondary" id="note">Nota interna</button><button class="btn btn-ghost" id="transfer">Transferir</button><button class="btn btn-primary" id="resolve">Resolver</button><button class="btn btn-ghost" id="transcript">Enviar transcrição</button></div>`,()=>{document.querySelector('#support-chat').onsubmit=e=>{e.preventDefault();const i=e.target.querySelector('input');addMessage(i.value,true);i.value=''};document.querySelector('#note').onclick=()=>addMessage('Nota interna: acompanhar retorno do navegador.',false,true);document.querySelector('#transfer').onclick=()=>toast('Ticket transferido para Equipe Técnica. Histórico preservado.');document.querySelector('#resolve').onclick=async()=>{await api(`/api/records/${t.id}/status`,{method:'POST',body:JSON.stringify({status:'RESOLVED'})});toast('Ticket resolvido.');closeModal()};document.querySelector('#transcript').onclick=()=>toast('Transcrição demonstrativa enviada. Notas internas foram excluídas.')})}
function finance(m){m.innerHTML=head(state.user.role==='DOCTOR'?'Financeiro demonstrativo':'Pagamentos','Valores preservados por compra.')+`<section class="metrics"><article class="metric"><span>Total no mês</span><strong>${money(4750)}</strong></article><article class="metric"><span>Hoje</span><strong>${money(300)}</strong></article><article class="metric"><span>Pendentes</span><strong>${money(100)}</strong></article><article class="metric"><span>Consultas</span><strong>95</strong></article></section><section class="panel"><p>Valores são demonstrativos. Não existe split ou liquidação financeira real.</p>${appointmentTable(state.appointments)}</section>`}
async function users(m){let list=[];try{list=await api('/api/users')}catch(e){}m.innerHTML=head('Gestão de usuários','Crie, encontre e gerencie acessos.',`<button class="btn btn-primary" id="new-user">Novo usuário</button>`)+`<section class="panel"><div class="filters"><input id="user-search" placeholder="Nome ou e-mail"><select><option>Todos os perfis</option><option>PATIENT</option><option>DOCTOR</option><option>SUPPORT</option><option>ADMIN</option></select></div><div class="table-wrap" id="user-list">${userTable(list)}</div></section>`;document.querySelector('#user-search').oninput=e=>document.querySelector('#user-list').innerHTML=userTable(list.filter(x=>JSON.stringify(x).toLowerCase().includes(e.target.value.toLowerCase())));document.querySelector('#new-user').onclick=()=>modal(`<h2>Novo usuário</h2><form id="user-form"><div class="field"><label>Perfil</label><select name="role"><option>PATIENT</option><option>DOCTOR</option><option>SUPPORT</option><option>ADMIN</option></select></div><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>E-mail</label><input type="email" name="email" required></div><p>A senha temporária será <b>Temporaria@123</b> e deverá ser trocada.</p><button class="btn btn-primary">Criar</button></form>`,()=>document.querySelector('#user-form').onsubmit=async e=>{e.preventDefault();await api('/api/records/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Usuário criado e ação registrada na auditoria.');setTimeout(()=>location.reload(),500)})}
const userTable=l=>`<table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Criado em</th></tr></thead><tbody>${l.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.role)}</td><td>${status(x.status)}</td><td>${date(x.createdAt)}</td></tr>`).join('')}</tbody></table>`;
function permissions(m){m.innerHTML=head('Permissões de Suporte','Princípio do menor privilégio aplicado no backend.')+`<section class="panel"><h2>Marina Costa</h2><p>suporte@fernandaazevedo.demo</p><form id="permissions">${['support.tickets.view','support.tickets.reply','support.tickets.transfer','support.tickets.close','support.transcript.send','support.attachments.upload','users.view','users.create','users.edit','consents.view_status','logs.view_limited'].map(p=>`<label class="check"><input type="checkbox" ${state.user.permissions.includes(p)||p!=='logs.view_limited'?'checked':''}><span>${p}</span></label>`).join('')}<p class="restricted">Acesso a prontuário clínico, pré-anamnese detalhada e documentos clínicos não é concedido ao Suporte.</p><button class="btn btn-primary">Salvar permissões</button></form></section>`;document.querySelector('#permissions').onsubmit=e=>{e.preventDefault();toast('Permissões atualizadas e auditadas (demonstração).')}}
async function campaigns(m){let list=[];try{list=await api('/api/campaigns')}catch(e){}m.innerHTML=head('Campanhas','Gerencie conteúdo público sem alterar os assets protegidos.',`<button class="btn btn-primary" id="new-campaign">Nova campanha</button>`)+`<section class="panel">${list.map(x=>`<article class="panel"><h3>${esc(x.title)}</h3><p>${esc(x.subtitle)}</p>${status(x.status)} <button class="btn btn-ghost campaign-status" data-id="${x.id}" data-status="${x.status==='PUBLISHED'?'PAUSED':'PUBLISHED'}">${x.status==='PUBLISHED'?'Pausar':'Publicar'}</button></article>`).join('')}</section>`;document.querySelectorAll('.campaign-status').forEach(b=>b.onclick=async()=>{await api(`/api/records/${b.dataset.id}/status`,{method:'POST',body:JSON.stringify({status:b.dataset.status})});toast('Campanha atualizada; a Home refletirá a alteração.');location.reload()});document.querySelector('#new-campaign').onclick=()=>modal(`<h2>Nova campanha</h2><form id="campaign-form"><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Subtítulo</label><textarea name="subtitle" required></textarea></div><div class="form-grid"><div class="field"><label>CTA</label><input name="ctaLabel" value="Saiba mais"></div><div class="field"><label>URL</label><input name="ctaUrl" value="#como-funciona"></div></div><div class="field"><label>Status</label><select name="status"><option>DRAFT</option><option>PUBLISHED</option></select></div><button class="btn btn-primary">Salvar campanha</button></form>`,()=>document.querySelector('#campaign-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));await api('/api/records/campaigns',{method:'POST',body:JSON.stringify({...b,owner:'PUBLIC',reference:'CAMP-'+Date.now()})});closeModal();toast('Campanha salva e auditada.');location.reload()})}
function settings(m){m.innerHTML=head('Valores e operação','Alterações refletem na Home e no checkout; compras antigas preservam seus valores.')+`<form class="panel" id="settings"><div class="form-grid"><div class="field"><label>Preço da consulta</label><input type="number" name="consultationPrice" min="1" step="0.01" value="${state.settings.consultationPrice}" required></div><div class="field"><label>Repasse-base médico</label><input type="number" name="doctorBasePayout" min="0" step="0.01" value="${state.settings.doctorBasePayout}" required></div><div class="field"><label>Moeda</label><select name="currency"><option>BRL</option></select></div><div class="field"><label>Texto exibido no site</label><input name="priceText" value="${esc(state.settings.priceText)}"></div></div><label class="check"><input type="checkbox" name="checkoutEnabled" ${state.settings.checkoutEnabled?'checked':''}><span>Ativar “Consultar agora”</span></label><button class="btn btn-primary">Salvar nova versão</button></form>`;document.querySelector('#settings').onsubmit=e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.consultationPrice=Number(b.consultationPrice);b.doctorBasePayout=Number(b.doctorBasePayout);b.checkoutEnabled=!!b.checkoutEnabled;confirmModal('Confirmar novos valores?',`Preço: ${money(b.consultationPrice)} • Repasse: ${money(b.doctorBasePayout)}`,async()=>{await api('/api/admin/settings/commercial',{method:'PUT',body:JSON.stringify(b)});toast('Valores salvos e registrados na auditoria.');setTimeout(()=>location.reload(),600)})}}
async function privacy(m){let list=[];try{list=await api('/api/consents')}catch(e){}m.innerHTML=head('Privacidade e consentimentos','Evidências operacionais, finalidades e versões.')+`<section class="panel"><p>Preferências revogáveis são separadas de dados necessários ao serviço e de obrigações legais/regulatórias.</p><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Versão</th><th>Aceite</th><th>Status</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(x.documentType)}</td><td>${esc(x.version)}</td><td>${esc(x.acceptedAt)}</td><td>${status(x.status)}</td><td><a href="/${x.documentType?.includes('Termos')?'termos':'privacidade'}">Visualizar documento</a></td></tr>`).join('')}</tbody></table></div><p class="restricted">Solicitações relativas a dados pessoais serão avaliadas conforme legislação e obrigações aplicáveis.</p></section>`}
async function audits(m){let list=[];try{list=await api('/api/audits')}catch(e){}m.innerHTML=head('Auditoria administrativa','Ações sensíveis sem senhas, tokens, cartões ou conteúdo clínico integral.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ator</th><th>Ação</th><th>Recurso</th></tr></thead><tbody>${list.map(x=>`<tr><td>${date(x.createdAt)}</td><td>${esc(x.owner)}</td><td>${esc(x.action)}</td><td>${esc(x.reference)}</td></tr>`).join('')}</tbody></table></div></section>`}
function profile(m){m.innerHTML=head('Meu perfil','Mantenha seus dados e preferências atualizados.')+`<form class="panel"><div class="form-grid"><div class="field"><label>Nome</label><input value="${esc(state.user.name)}"></div><div class="field"><label>E-mail</label><input value="${esc(state.user.email)}" disabled></div><div class="field"><label>Telefone</label><input placeholder="(00) 00000-0000"></div><div class="field"><label>Status da conta</label><input value="${state.user.status}" disabled></div></div><button class="btn btn-primary" type="button" onclick="document.querySelector('#toast').textContent='Perfil atualizado';document.querySelector('#toast').classList.add('show')">Salvar perfil</button></form>`}
function modal(html,ready){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><span></span><button class="icon-btn" aria-label="Fechar">×</button></div>${html}</section></div>`;document.querySelector('.modal .icon-btn').onclick=closeModal;document.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};ready?.();document.querySelector('.modal input,.modal button,.modal select')?.focus()}
function closeModal(){document.querySelector('#modal-root').innerHTML=''}

async function consultationRobust(m){
  const isDoctor=state.user.role==='DOCTOR';
  m.innerHTML=head('Teleconsulta','Ambiente protegido • câmera e microfone sob seu controle • não gravando')+`<div class="chat-layout consultation-layout"><section class="video-stage"><div class="video-topbar"><span class="badge" id="connection-state">Preparando dispositivos</span><strong id="timer">00:00</strong></div><div class="video-placeholder"><span class="avatar">${isDoctor?'JA':'FA'}</span><h2>${isDoctor?'João Almeida':'Dra. Fernanda Azevedo'}</h2><p>${isDoctor?'Paciente':'Clínica geral • CRM DEMO'}</p></div><div class="self-video-wrap"><video class="self-video" id="self" autoplay muted playsinline aria-label="Sua câmera"></video><span class="self-label">Você</span></div><div id="media-alert" class="media-alert" hidden><b id="media-title">Câmera indisponível</b><small id="media-error">Verifique a permissão do navegador.</small><button class="btn btn-secondary" id="retry-camera">Tentar novamente</button></div><div class="video-controls"><button class="round-btn" id="mic" aria-label="Desativar microfone" title="Microfone">🎙️</button><button class="round-btn" id="cam" aria-label="Desativar câmera" title="Câmera">📹</button><button class="round-btn" id="devices-call" aria-label="Configurar dispositivos" title="Dispositivos">⚙️</button><button class="round-btn leave-call" id="leave" aria-label="Sair da sala sem finalizar" title="Sair">↗</button><button class="round-btn end-call" id="end" aria-label="Finalizar consulta" title="Finalizar">⏹</button></div></section><section class="panel chat-panel"><div class="panel-head"><div><h3>Chat clínico</h3><small>Mensagens e arquivos vinculados à consulta</small></div><span class="badge">Seguro</span></div><div class="chat-toolbar"><button class="attach-btn" id="files" aria-label="Anexar documento, imagem ou áudio">📎</button><button class="attach-btn" id="documents-call" aria-label="Ver documentos da consulta">▤</button><span id="upload-status"><small>PDF, imagens, DOCX ou áudio</small></span></div><div class="messages" id="messages"><div class="message">Olá! Já li suas respostas. Como você está se sentindo agora?<small><br>Entregue • agora</small></div></div><form class="composer" id="chat"><input aria-label="Mensagem clínica" required placeholder="Escreva uma mensagem"><button class="btn btn-primary">Enviar</button></form><input id="upload" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.doc,.docx,.wav,.mp3,.m4a" hidden></section></div>`;
  let videoStream=null,audioStream=null,secs=0;
  const timer=setInterval(()=>{const el=document.querySelector('#timer');if(!el)return clearInterval(timer);secs++;el.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`},1000);
  const setMediaError=(error)=>{const alert=document.querySelector('#media-alert'),detail=document.querySelector('#media-error'),badge=document.querySelector('#connection-state');alert.hidden=false;badge.textContent='Dispositivo pendente';badge.classList.add('warning');const messages={NotAllowedError:'O navegador bloqueou a câmera para este endereço. Clique no cadeado ao lado do endereço, permita Câmera e recarregue.',NotFoundError:'Nenhuma câmera foi encontrada. Conecte uma câmera e tente novamente.',NotReadableError:'A câmera está sendo usada por outro aplicativo. Feche-o e tente novamente.',OverconstrainedError:'A câmera selecionada não está disponível. Tente a seleção automática.',SecurityError:'O navegador bloqueou o acesso por uma configuração de segurança.'};detail.textContent=messages[error?.name]||`Não foi possível iniciar a câmera (${error?.name||'erro desconhecido'}). Tente novamente.`};
  const startCamera=async()=>{const alert=document.querySelector('#media-alert'),badge=document.querySelector('#connection-state'),video=document.querySelector('#self');alert.hidden=true;badge.textContent='Solicitando câmera';badge.classList.remove('warning');videoStream?.getTracks().forEach(t=>t.stop());try{if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)throw Object.assign(new Error('Contexto sem suporte'),{name:'SecurityError'});videoStream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false});video.srcObject=videoStream;await video.play();badge.textContent='Câmera ativa';badge.classList.remove('warning');try{audioStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});}catch(audioError){document.querySelector('#mic').classList.add('btn-danger');document.querySelector('#mic').setAttribute('aria-label','Microfone indisponível');toast('A câmera está ativa. O microfone não foi autorizado e pode ser liberado separadamente.')}toast('Sua câmera está ativa dentro da consulta.')}catch(error){setMediaError(error)}};
  document.querySelector('#retry-camera').onclick=startCamera;await startCamera();
  const form=document.querySelector('#chat');form.onsubmit=e=>{e.preventDefault();const input=form.querySelector('input');addMessage(input.value,true);input.value=''};
  document.querySelector('#files').onclick=()=>document.querySelector('#upload').click();document.querySelector('#upload').onchange=async e=>{document.querySelector('#upload-status').innerHTML='<small>Analisando arquivo…</small>';await uploadFile(e);document.querySelector('#upload-status').innerHTML='<small>Arquivo processado com segurança demonstrativa</small>'};
  document.querySelector('#documents-call').onclick=()=>modal(`<h2>Documentos da consulta</h2><div class="file-preview"><span>📄</span><div><b>Orientações do atendimento</b><small><br>Documento demonstrativo</small></div></div><div class="file-preview"><span>▤</span><div><b>Solicitação de exame</b><small><br>Sem validade médica real</small></div></div>`);
  document.querySelector('#devices-call').onclick=async()=>{let devices=[];try{devices=await navigator.mediaDevices.enumerateDevices()}catch{}modal(`<h2>Dispositivos disponíveis</h2><p><b>Câmeras:</b> ${devices.filter(d=>d.kind==='videoinput').length||'não identificadas'}<br><b>Microfones:</b> ${devices.filter(d=>d.kind==='audioinput').length||'não identificados'}</p><p>Se a câmera estiver ocupada, feche Teams, Zoom ou outro aplicativo que possa estar usando-a.</p><button class="btn btn-primary" id="modal-retry">Testar novamente</button>`,()=>document.querySelector('#modal-retry').onclick=()=>{closeModal();startCamera()})};
  document.querySelector('#leave').onclick=()=>confirmModal('Sair da sala?','A consulta continuará ativa e você poderá retornar.',()=>{videoStream?.getTracks().forEach(t=>t.stop());audioStream?.getTracks().forEach(t=>t.stop());location.href=`/${rolePath(state.user.role)}/dashboard`});
  document.querySelector('#end').onclick=()=>confirmModal(isDoctor?'Finalizar atendimento?':'Finalizar sua participação?','A consulta será encerrada e salva no histórico.',()=>{videoStream?.getTracks().forEach(t=>t.stop());audioStream?.getTracks().forEach(t=>t.stop());toast('Consulta finalizada e salva.');setTimeout(()=>location.href=`/${rolePath(state.user.role)}/historico`,700)});
  document.querySelector('#mic').onclick=e=>{const track=audioStream?.getAudioTracks()[0];if(track)track.enabled=!track.enabled;e.currentTarget.classList.toggle('btn-danger',!track||!track.enabled)};document.querySelector('#cam').onclick=e=>{const track=videoStream?.getVideoTracks()[0];if(track)track.enabled=!track.enabled;e.currentTarget.classList.toggle('btn-danger',!track||!track.enabled)};
}

consultation=consultationRobust;
function confirmModal(t,b,yes){modal(`<h2>${esc(t)}</h2><p>${esc(b)}</p><div class="actions"><button class="btn btn-ghost" id="cancel-modal">Cancelar</button><button class="btn btn-primary" id="confirm-modal">Confirmar</button></div>`,()=>{document.querySelector('#cancel-modal').onclick=closeModal;document.querySelector('#confirm-modal').onclick=()=>{closeModal();yes()}})}
init();
